# Generated by scripts/cask.sh in tyldra/keynook; the release workflow
# updates it. Edit the script there, not this file.
cask "keynook" do
  version "0.1.0"
  sha256 "257e682c876390eb9862146f94d20b4dbe0d66b0bbf750320a47934ad09a09d9"

  url "https://github.com/tyldra/keynook/releases/download/v#{version}/keynook-#{version}-macos.tar.gz"
  name "Keynook"
  desc "API key manager backed by the login Keychain"
  homepage "https://github.com/tyldra/keynook"

  livecheck do
    url :url
    strategy :github_latest
  end

  depends_on macos: :sequoia

  binary "keynook"

  # Releases are signed ad hoc, not notarized, so Gatekeeper would refuse to run
  # a quarantined copy. The archive's checksum is pinned above, and each release
  # has a build provenance attestation.
  postflight_steps do
    run "/usr/bin/xattr",
        args:           ["-dr", "com.apple.quarantine", "{{staged_path}}/keynook"],
        writable_paths: ["keynook"],
        writable_base:  :staged_path
  end

  uninstall launchctl: "keynook.publish"

  zap trash: [
    "~/.config/keynook",
    "~/Library/Logs/keynook.log",
  ]

  caveats <<~EOS
    Connect Keynook to your shell and to apps:
      echo 'eval "$(keynook init zsh)"' >> ~/.zshrc
      keynook agent install
      keynook doctor

    Your keys stay in the login Keychain after an uninstall. To delete them
    too, run keynook remove NAME for each key first.
  EOS
end
